cat >> src/checkout.test.ts <<'EOF'

describe("bug fixes", () => {
  const shop = createCatalog([
    { sku: "TASSE", name: "Espressotasse", priceCents: 1500, vat: "standard" },
    { sku: "KAUGUMMI", name: "Kaugummi", priceCents: 99, vat: "reduced" },
    { sku: "BROT", name: "Ruchbrot", priceCents: 290, vat: "reduced" },
  ]);
  const promos: Promotion[] = [
    { code: "TASSE3", kind: "multibuy", sku: "TASSE", buy: 3, pay: 2 },
    { code: "FUENFZIG", kind: "fixed", amountCents: 5000 },
    { code: "ZEHN", kind: "percent", percent: 10 },
    { code: "ZEHN50", kind: "percent", percent: 10, minSubtotalCents: 5000 },
  ];

  test("multibuy only counts complete groups", () => {
    expect(checkout([{ sku: "TASSE", qty: 2 }], shop, promos, "TASSE3").discountCents).toBe(0);
    expect(checkout([{ sku: "TASSE", qty: 4 }], shop, promos, "TASSE3").discountCents).toBe(1500);
    expect(checkout([{ sku: "TASSE", qty: 6 }], shop, promos, "TASSE3").discountCents).toBe(3000);
  });

  test("lines are exact, only the total is rounded to 5 Rappen", () => {
    const receipt = checkout([{ sku: "KAUGUMMI", qty: 3 }], shop);
    expect(receipt.lines[0].lineCents).toBe(297);
    expect(receipt.subtotalCents).toBe(297);
    expect(receipt.totalCents).toBe(295);
  });

  test("fixed voucher is capped at the subtotal", () => {
    const receipt = checkout([{ sku: "BROT", qty: 2 }], shop, promos, "FUENFZIG");
    expect(receipt.discountCents).toBe(580);
    expect(receipt.totalCents).toBe(0);
  });

  test("VAT accounts for the coupon", () => {
    const receipt = checkout([{ sku: "TASSE", qty: 4 }], shop, promos, "ZEHN");
    expect(receipt.totalCents).toBe(5400);
    expect(receipt.vat).toEqual({ standard: 405, reduced: 0 });
  });

  test("VAT splits the discount proportionally between rates", () => {
    // subtotal 1790 (1500 standard, 290 reduced), discount 179
    // reduced share round(179 * 290 / 1790) = 29, standard share 150
    const receipt = checkout(
      [
        { sku: "TASSE", qty: 1 },
        { sku: "BROT", qty: 1 },
      ],
      shop,
      promos,
      "ZEHN",
    );
    expect(receipt.discountCents).toBe(179);
    expect(receipt.vat).toEqual({ standard: 101, reduced: 7 });
  });
});

describe("minimum order value", () => {
  const shop = createCatalog([
    { sku: "TASSE", name: "Espressotasse", priceCents: 1500, vat: "standard" },
  ]);
  const promos: Promotion[] = [
    { code: "ZEHN50", kind: "percent", percent: 10, minSubtotalCents: 5000 },
  ];

  test("below the minimum no discount is given and a notice is set", () => {
    const receipt = checkout([{ sku: "TASSE", qty: 3 }], shop, promos, "ZEHN50");
    expect(receipt.discountCents).toBe(0);
    expect(receipt.totalCents).toBe(4500);
    expect(receipt.couponCode).toBe("ZEHN50");
    expect(receipt.notice).toBe("Coupon ZEHN50 requires a minimum order of CHF 50.00");
  });

  test("at or above the minimum the coupon applies", () => {
    const receipt = checkout(
      [
        { sku: "TASSE", qty: 3 },
        { sku: "TASSE", qty: 1 },
      ],
      shop,
      promos,
      "ZEHN50",
    );
    expect(receipt.discountCents).toBe(600);
    expect(receipt.notice).toBeUndefined();
  });

  test("unknown coupon still throws", () => {
    expect(() => checkout([{ sku: "TASSE", qty: 1 }], shop, promos, "GRATIS")).toThrow(
      "Unknown coupon code: GRATIS",
    );
  });
});
